using MediatR;using Namaa.Application.Abstractions.Authentication;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Common.Errors;using Namaa.Application.PaymentVouchers.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;using Namaa.Domain.Entities;namespace Namaa.Application.PaymentVouchers.Commands.CreatePaymentVoucher;public sealed class CreatePaymentVoucherCommandHandler(IPaymentVoucherRepository repository,ICurrentUser currentUser,IApplicationDbContext db):IRequestHandler<CreatePaymentVoucherCommand,Result<PaymentVoucherDto>>{public async Task<Result<PaymentVoucherDto>>Handle(CreatePaymentVoucherCommand request,CancellationToken cancellationToken){if(!currentUser.IsAuthenticated||currentUser.UserId is not long actorUserId)return Result.Failure<PaymentVoucherDto>(ApplicationErrors.Unauthenticated);if(await repository.ExistsByNumberAsync(request.VoucherNumber,cancellationToken))return Result.Failure<PaymentVoucherDto>(PaymentVoucherErrors.Duplicate);var e=PaymentVoucher.Create(request.VoucherNumber,request.VoucherDate,request.PaymentMethod,request.Amount,actorUserId,request.SupplierId,request.BeneficiaryName,request.ProjectId,request.ReferenceNumber,request.Notes);await repository.AddAsync(e,cancellationToken);await db.SaveChangesAsync(cancellationToken);return Result.Success(PaymentVoucherDto.FromEntity(e));}}
